-- Additive local implementation. Never replay historical migrations on hosted DBs.
begin;

create or replace function private.prevent_profile_role_escalation()
returns trigger language plpgsql security definer set search_path='' as $$
declare previous_role text;
begin
  previous_role := case when tg_op='INSERT' then 'user' else old.role end;
  if new.role is distinct from previous_role then
    if coalesce(auth.jwt()->>'role','')='service_role'
       or (tg_op='UPDATE' and private.has_role(array['super_admin'])) then
      insert into public.admin_audit_logs(actor_id,action,resource_type,resource_id,safe_metadata)
      values(auth.uid(),'profile_role_change','profile',new.id::text,
             jsonb_build_object('from',previous_role,'to',new.role,'operation',tg_op));
    else
      raise exception 'role_change_forbidden' using errcode='42501';
    end if;
  end if;
  return new;
end $$;
drop trigger if exists rad_profile_insert_role_guard on public.profiles;
create trigger rad_profile_insert_role_guard before insert on public.profiles
for each row execute function private.prevent_profile_role_escalation();
revoke insert on public.profiles from authenticated;
revoke insert(role) on public.profiles from authenticated;
grant insert(id,full_name,email,phone,country) on public.profiles to authenticated;
revoke execute on all functions in schema private from public,anon,authenticated;
grant execute on function private.has_role(text[]) to anon,authenticated;
alter default privileges for role postgres in schema public revoke execute on functions from public;
alter default privileges for role postgres in schema private revoke execute on functions from public;

create table private.rad_contract_schemas(name text primary key, schema jsonb not null);
alter table private.rad_contract_schemas enable row level security;
revoke all on private.rad_contract_schemas from public,anon,authenticated,service_role;

-- Closed JSON-schema subset used by the reviewed contract registry. No dynamic SQL.
create function private.rad_schema_valid(s jsonb,v jsonb,depth integer default 0)
returns boolean language plpgsql stable set search_path='' as $$
declare child jsonb; k text; val jsonb; typ text; matches integer; num numeric;
begin
  if depth>24 or v is null then return false; end if;
  if s ? '$ref' then
    select schema into child from private.rad_contract_schemas where name=split_part(s->>'$ref','/',3);
    return child is not null and private.rad_schema_valid(child,v,depth+1);
  end if;
  if s ? 'anyOf' or s ? 'oneOf' then
    select count(*) into matches from jsonb_array_elements(coalesce(s->'anyOf',s->'oneOf')) a
    where private.rad_schema_valid(a,v,depth+1);
    return case when s ? 'oneOf' then matches=1 else matches>0 end;
  end if;
  if s ? 'const' and v<>s->'const' then return false; end if;
  if s ? 'enum' and not (s->'enum' @> jsonb_build_array(v)) then return false; end if;
  typ:=jsonb_typeof(v);
  if s ? 'type' and s->>'type'<>typ and not (s->>'type'='integer' and typ='number') then return false; end if;
  if typ='object' then
    for k in select jsonb_array_elements_text(coalesce(s->'required','[]')) loop
      if not v ? k then return false; end if;
    end loop;
    for k,val in select * from jsonb_each(v) loop
      if not coalesce(s->'properties','{}') ? k then
        if s->'additionalProperties'='false'::jsonb then return false; end if;
      elsif not private.rad_schema_valid(s->'properties'->k,val,depth+1) then return false;
      end if;
    end loop;
  elsif typ='array' then
    if jsonb_array_length(v)<coalesce((s->>'minItems')::integer,0)
       or jsonb_array_length(v)>coalesce((s->>'maxItems')::integer,10000) then return false; end if;
    if s->>'uniqueItems'='true' and (select count(distinct x) from jsonb_array_elements(v) x)<>jsonb_array_length(v) then return false; end if;
    if s ? 'items' then
      for child in select * from jsonb_array_elements(v) loop
        if not private.rad_schema_valid(s->'items',child,depth+1) then return false; end if;
      end loop;
    end if;
  elsif typ='string' then
    k:=v#>>'{}';
    if char_length(k)<coalesce((s->>'minLength')::integer,0)
       or char_length(k)>coalesce((s->>'maxLength')::integer,2000000)
       or (s ? 'pattern' and not k ~ (s->>'pattern')) then return false; end if;
    if s->>'format'='date' then
      if to_char(k::date,'YYYY-MM-DD')<>k then return false; end if;
    end if;
    if s->>'format'='date-time' then perform k::timestamptz; end if;
  elsif typ='number' then
    num:=(v#>>'{}')::numeric;
    if s->>'type'='integer' and trunc(num)<>num then return false; end if;
    if (s ? 'minimum' and num<(s->>'minimum')::numeric)
       or (s ? 'maximum' and num>(s->>'maximum')::numeric) then return false; end if;
  end if;
  return true;
exception when invalid_text_representation or datetime_field_overflow or invalid_datetime_format or numeric_value_out_of_range then
  return false;
end $$;

create function private.rad_assert_request(operation text,body jsonb) returns void
language plpgsql stable set search_path='' as $$
declare s jsonb;
begin
  select schema into s from private.rad_contract_schemas where name=replace(operation,'-','_')||'_request';
  if s is null or not private.rad_schema_valid(s,body) then
    raise exception 'invalid_request' using errcode='PT422';
  end if;
end $$;

create function private.rad_require_admin(human boolean default true) returns uuid
language plpgsql stable security definer set search_path='' as $$
begin
  if auth.uid() is null or coalesce(auth.jwt()->>'role','')<>'authenticated'
     or not private.has_role(array['admin','super_admin']) then
    raise exception 'forbidden' using errcode='PT403';
  end if;
  return auth.uid();
end $$;

create function private.rad_require_owner() returns uuid
language plpgsql stable set search_path='' as $$
begin
  if auth.uid() is null or coalesce(auth.jwt()->>'role','')<>'authenticated' then
    raise exception 'authentication_required' using errcode='PT401';
  end if;
  return auth.uid();
end $$;

create function private.rad_envelope(data jsonb,locale text default null,page jsonb default null)
returns jsonb language sql volatile set search_path='' as $$
  select jsonb_build_object('data',data,'meta',jsonb_build_object(
    'request_id',gen_random_uuid(),'contract_version','1','server_time',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'requested_locale',locale,'resolved_locale',locale,'fallback_used',false))
    || case when page is null then '{}'::jsonb else jsonb_build_object('page',page) end;
$$;

create table private.rad_idempotency(
 actor_id uuid not null,operation text not null,request_key uuid not null,
 body_hash text not null,result jsonb,created_at timestamptz not null default now(),
 primary key(actor_id,operation,request_key)
);
alter table private.rad_idempotency enable row level security;
revoke all on private.rad_idempotency from public,anon,authenticated,service_role;

create function private.rad_begin_mutation(operation text,body jsonb) returns jsonb
language plpgsql set search_path='' as $$
declare actor uuid:=private.rad_require_owner(); prior private.rad_idempotency; hash text:=encode(extensions.digest(body::text,'sha256'),'hex');
begin
  perform private.rad_assert_request(operation,body);
  perform pg_catalog.pg_advisory_xact_lock(hashtextextended(actor::text||operation||(body->>'request_key'),0));
  select * into prior from private.rad_idempotency where actor_id=actor and rad_idempotency.operation=rad_begin_mutation.operation and request_key=(body->>'request_key')::uuid;
  if found then
    if prior.body_hash<>hash then raise exception 'idempotency_conflict' using errcode='PT409'; end if;
    return prior.result;
  end if;
  insert into private.rad_idempotency values(actor,operation,(body->>'request_key')::uuid,hash,null,now());
  return null;
end $$;

create function private.rad_finish_mutation(operation text,body jsonb,result jsonb) returns jsonb
language plpgsql set search_path='' as $$
begin
  update private.rad_idempotency set result=rad_finish_mutation.result
  where actor_id=auth.uid() and rad_idempotency.operation=rad_finish_mutation.operation and request_key=(body->>'request_key')::uuid;
  return result;
end $$;

create table private.rad_page_tokens(
 token uuid primary key default gen_random_uuid(),actor text not null,filter_hash text not null,
 position jsonb not null,version text not null,expires_at timestamptz not null default now()+interval '15 minutes'
);
alter table private.rad_page_tokens enable row level security;
revoke all on private.rad_page_tokens from public,anon,authenticated,service_role;

create function private.rad_page_position(body jsonb,version text) returns jsonb
language plpgsql set search_path='' as $$
declare p private.rad_page_tokens; filter_hash text:=md5((body-'cursor')::text);
begin
  if body->>'cursor' is null then return null; end if;
  if body->>'cursor' !~ '^[0-9a-f-]{36}$' then raise exception 'cursor_expired' using errcode='PT409'; end if;
  select * into p from private.rad_page_tokens where token=(body->>'cursor')::uuid;
  if not found or p.expires_at<=now() or p.actor<>coalesce(auth.uid()::text,'public')
     or p.filter_hash<>filter_hash or p.version<>version then
    raise exception 'cursor_expired' using errcode='PT409';
  end if;
  return p.position;
end $$;

create function private.rad_page(body jsonb,version text,cursor_position jsonb,has_more boolean) returns jsonb
language plpgsql set search_path='' as $$
declare token uuid;
begin
  if has_more then
    insert into private.rad_page_tokens(actor,filter_hash,position,version)
    values(coalesce(auth.uid()::text,'public'),md5((body-'cursor')::text),cursor_position,version) returning rad_page_tokens.token into token;
  end if;
  return jsonb_build_object('next_cursor',token,'has_more',has_more);
end $$;

